const T = BR.THREE, scene = BR.scene, clamp = BR.clamp;
const ease = t => 1 - Math.pow(1 - t, 3);
const root = new T.Group(); root.userData.nuke = true; scene.add(root);
const fx = [];
let open = true, armed = false, busy = false, target = null, shown = null, mapOpen = false, dragging = false, uiT = 0;
let destroy = !!BR.storage.get('destroy', true);
let shakeT = 0, shakeDur = 1, shakeAmp = 0;
const C0 = new T.Color(0xff8a2a), C1 = new T.Color(0x57504a), C2 = new T.Color(0x70675e);

// Расширяем штатные лимиты физически оторванных деталей до профиля Maximum.
try {
  const profiles = BR.G && BR.G.PROFILES;
  if (profiles) for (const k in profiles) Object.assign(profiles[k], { pieces: 70, pieceLife: 45, piecePts: 256, pieceSub: 3, deb: 90, sm: 360, fx: 1 });
} catch (e) { console.warn('[nuke-remote] profile tuning skipped', e); }

/* ---------- Стили ---------- */
const css = document.createElement('style');
css.textContent = `
.nk-b{display:block;width:100%;min-height:42px;margin:0;padding:8px;border-radius:12px;border:1px solid rgba(0,0,0,.75);background:linear-gradient(#5a626d,#3c424a);color:#fff;font:inherit;letter-spacing:1px;cursor:pointer;touch-action:manipulation;box-shadow:0 3px 0 #14171b,inset 0 1px 0 rgba(255,255,255,.2);transition:transform .08s,box-shadow .08s}
.nk-b:active:not(:disabled){transform:translateY(2px);box-shadow:0 1px 0 #14171b,inset 0 1px 0 rgba(255,255,255,.2)}
.nk-b:disabled{opacity:.45;cursor:default}
.nk-blue{background:linear-gradient(#3d8ae0,#225a9f);box-shadow:0 3px 0 #0f2d52,inset 0 1px 0 rgba(255,255,255,.3)}
.nk-go{font-size:18px;letter-spacing:4px;font-weight:800;background:radial-gradient(circle at 50% 28%,#ff7e6c,#c4160a 72%);box-shadow:0 3px 0 #560a05,0 0 18px rgba(255,40,20,.5),inset 0 1px 0 rgba(255,255,255,.3);position:relative;overflow:hidden}
.nk-go.lock{background:#58231f;box-shadow:0 3px 0 #2a0f0d;color:rgba(255,255,255,.5)}
.nk-go.lock::after{content:'';position:absolute;inset:0;background:repeating-linear-gradient(-45deg,rgba(255,200,40,.30) 0 8px,rgba(0,0,0,.32) 8px 16px)}
.nk-lcd{padding:8px 10px;border-radius:10px;background:#09170f;border:1px solid #000;box-shadow:inset 0 2px 8px rgba(0,0,0,.85),0 1px 0 rgba(255,255,255,.1);font:700 11px/1.5 ui-monospace,Menlo,Consolas,monospace;color:#6dffa8;text-shadow:0 0 6px rgba(80,255,150,.45);background-image:repeating-linear-gradient(0deg,rgba(0,0,0,.2) 0 1px,transparent 1px 3px)}
.nk-lcd b{display:block;font-weight:800}
.nk-lcd i{display:block;font-style:normal;opacity:.75}
#nk-panel{position:fixed;right:16px;bottom:96px;z-index:9999;width:240px;max-height:calc(100vh - 120px);overflow:auto;padding:12px 12px 14px;border-radius:24px;background:linear-gradient(165deg,#32363e 0%,#1c1f24 55%,#14161a 100%);border:1px solid rgba(255,255,255,.15);box-shadow:0 14px 34px rgba(0,0,0,.6),inset 0 1px 0 rgba(255,255,255,.18),inset 0 -2px 0 rgba(0,0,0,.4);font:600 13px system-ui,-apple-system,sans-serif;color:#e4e8ed;display:none;user-select:none;-webkit-user-select:none;touch-action:manipulation}
#nk-panel .hd{display:flex;align-items:center;gap:9px;margin-bottom:10px}
#nk-panel .led{width:10px;height:10px;border-radius:50%;background:#e0a21a;box-shadow:0 0 8px #e0a21a}
#nk-panel[data-s=ready] .led{background:#ff3b2e;box-shadow:0 0 10px #ff3b2e;animation:nkb 1s infinite}
#nk-panel[data-s=busy] .led{background:#39e58c;box-shadow:0 0 10px #39e58c}
#nk-panel .ti{flex:1;font-size:13px;letter-spacing:3px;color:#ffd24a}
#nk-panel .ti small{font-size:10px;letter-spacing:1px;color:#8b94a0;font-weight:600}
#nk-panel .lcd2{margin-bottom:10px}
#nk-panel .r{display:flex;gap:8px;margin-bottom:8px}
#nk-panel .r>*{flex:1}
#nk-panel .r2 .nk-b{min-height:36px;font-size:11px;letter-spacing:0;padding:6px}
#nk-panel .r1 .nk-b{height:56px}
@keyframes nkb{50%{opacity:.35}}
#nk-toggle{position:fixed;display:none;right:calc(env(safe-area-inset-right,0px) + 14px);top:calc(env(safe-area-inset-top,0px) + 154px);z-index:9998;width:50px;height:50px;border:2px solid rgba(255,255,255,.7);border-radius:15px;background:linear-gradient(145deg,#59616b,#252a32);color:#ffd24a;font:900 23px/1 system-ui,sans-serif;box-shadow:0 5px 16px rgba(0,0,0,.45);touch-action:manipulation;align-items:center;justify-content:center}
#nk-toggle:active{transform:scale(.94)}
#nk-toggle.on{border-color:#ff5a4a;box-shadow:0 0 14px rgba(255,60,40,.7),0 5px 16px rgba(0,0,0,.45)}
@media (pointer:coarse),(max-width:700px){
#nk-panel{right:calc(env(safe-area-inset-right,0px) + 76px);top:calc(env(safe-area-inset-top,0px) + 154px);bottom:auto;width:min(240px,calc(100vw - 100px));max-height:calc(100vh - 170px);padding:10px 10px 12px}
#nk-toggle{width:54px;height:54px;font-size:25px}}
#nk-flash{position:fixed;inset:0;z-index:10000;pointer-events:none;opacity:0;background:radial-gradient(circle,#fff,#ffe9b5)}
body.nk-aim,body.nk-aim *{cursor:crosshair!important}
#nk-map{position:fixed;inset:0;z-index:10001;display:none;background:radial-gradient(circle at 50% 30%,rgba(22,29,38,.95),rgba(5,7,10,.98));-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);font:600 13px system-ui,-apple-system,sans-serif;color:#e4e8ed;user-select:none;-webkit-user-select:none;touch-action:none}
#nk-map .w{position:absolute;top:calc(env(safe-area-inset-top,0px) + 10px);right:calc(env(safe-area-inset-right,0px) + 12px);bottom:calc(env(safe-area-inset-bottom,0px) + 10px);left:calc(env(safe-area-inset-left,0px) + 12px);display:flex;flex-direction:column;gap:10px}
#nk-map .mh{display:flex;align-items:center;gap:10px}
#nk-map .mt{flex:1;font-size:14px;letter-spacing:3px;color:#ffd24a}
#nk-map .mx{width:40px;height:40px;border-radius:12px;border:1px solid rgba(255,255,255,.22);background:rgba(255,255,255,.08);color:#fff;font:700 18px/1 system-ui,sans-serif;cursor:pointer;touch-action:manipulation}
#nk-map .mb{flex:1;min-height:0;display:flex;flex-direction:column;gap:10px}
#nk-map .mc{flex:1;min-height:0;min-width:0;position:relative}
#nk-map canvas{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);border-radius:14px;border:1px solid rgba(255,255,255,.2);box-shadow:0 10px 40px rgba(0,0,0,.65);cursor:crosshair;touch-action:none;display:block}
#nk-map .ms{display:flex;flex-direction:column;gap:8px}
#nk-map .lg{font-size:11px;font-weight:500;color:#9aa4b0;line-height:1.5}
#nk-map .lg span{color:#e4e8ed;font-weight:700}
#nk-map .rw{display:flex;gap:8px}
#nk-map .rw .nk-b{height:50px}
@media (min-aspect-ratio:1/1){#nk-map .mb{flex-direction:row}#nk-map .ms{width:210px;justify-content:center}}`;
document.head.appendChild(css);

/* ---------- Пульт ---------- */
const q = id => document.getElementById(id);
const panel = document.createElement('div');
panel.id = 'nk-panel'; panel.dataset.s = 'idle';
panel.innerHTML = '<div class="hd"><div class="led"></div><div class="ti">ПУЛЬТ <small>P</small></div></div>' +
  '<div class="nk-lcd lcd2"><b id="nk-l1"></b><i id="nk-l2"></i></div>' +
  '<div class="r r1"><button class="nk-b nk-blue" id="nk-om" type="button">🗺 КАРТА</button><button class="nk-b nk-go lock" id="nk-go" type="button">ПУСК</button></div>' +
  '<div class="r r2"><button class="nk-b" id="nk-dm" type="button"></button><button class="nk-b" id="nk-aim" type="button"></button></div>';
document.body.appendChild(panel);

const toggleButton = document.createElement('button');
toggleButton.id = 'nk-toggle'; toggleButton.type = 'button'; toggleButton.textContent = '☢';
toggleButton.setAttribute('aria-label', 'Открыть ядерный пульт');
toggleButton.title = 'Ядерный пульт (P)'; document.body.appendChild(toggleButton);
const fl = document.createElement('div'); fl.id = 'nk-flash'; document.body.appendChild(fl);

/* ---------- Карта ---------- */
const mapEl = document.createElement('div');
mapEl.id = 'nk-map';
mapEl.innerHTML = '<div class="w"><div class="mh"><div class="mt">☢ ТАКТИЧЕСКАЯ КАРТА</div><button class="mx" id="nk-mx" type="button" aria-label="Закрыть карту">✕</button></div>' +
  '<div class="mb"><div class="mc" id="nk-mc"><canvas id="nk-cv"></canvas></div>' +
  '<div class="ms"><div class="nk-lcd"><b id="nk-m1"></b><i id="nk-m2"></i><i id="nk-m3"></i></div>' +
  '<div class="lg">Тапни по карте — поставится метка, её можно двигать пальцем.<br><span style="color:#38d6ff">▲</span> вы · <span style="color:#ff5a4a">⊕</span> цель · <span style="color:#ff5a4a">●</span> шар 55 м · <span style="color:#ff9a30">◌</span> волна 440 м</div>' +
  '<div class="rw"><button class="nk-b" id="nk-mclr" type="button">Сбросить</button><button class="nk-b nk-go lock" id="nk-mgo" type="button">ПУСК</button></div></div></div></div>';
document.body.appendChild(mapEl);
const mapCv = q('nk-cv'), mctx = mapCv.getContext('2d');
let base = null, side = 0, dpr = 1;

[panel, mapEl].forEach(el => ['pointerdown', 'pointerup', 'mousedown', 'touchstart', 'click', 'wheel'].forEach(ev => el.addEventListener(ev, e => e.stopPropagation())));
mapEl.addEventListener('contextmenu', e => e.preventDefault());
toggleButton.addEventListener('pointerdown', e => e.stopPropagation());
toggleButton.addEventListener('click', e => { e.stopPropagation(); open = !open; if (!open && armed) setArmed(false); updateUI(); });

function geo() {
  const G = BR.G || {}, n = v => typeof v === 'number' && isFinite(v) && v > 0;
  return { N: n(G.N) ? G.N : 20, CELL: n(G.CELL) ? G.CELL : 44, BLOCK: n(G.BLOCK) ? G.BLOCK : 28, HALF: n(G.HALF) ? G.HALF : 264, BOUND: n(G.BOUND) ? G.BOUND : 272 };
}
function focus() {
  let F = null;
  try { F = BR.G && typeof BR.G.foc === 'function' ? BR.G.foc() : BR.player; } catch (e) { F = BR.player; }
  return F && isFinite(F.x) && isFinite(F.z) ? F : null;
}
function groundAt(x, z) {
  try {
    const G = BR.G;
    if (G && typeof G.groundH === 'function') { const y = G.groundH(x, z, 0); if (isFinite(y) && Math.abs(y) < 100) return y; }
  } catch (e) { }
  return 0;
}
function sector(x, z) {
  const g = geo();
  const i = clamp(Math.floor((x + g.HALF) / g.CELL), 0, g.N - 1), j = clamp(Math.floor((z + g.HALF) / g.CELL), 0, g.N - 1);
  return String.fromCharCode(65 + i % 26) + '-' + (j + 1);
}
function distToMe() {
  const F = focus(); if (!F || !target) return null;
  return Math.round(Math.hypot(F.x - target.x, F.z - target.z));
}
function rr(c, x, y, w, h, r) {
  c.beginPath(); c.moveTo(x + r, y); c.arcTo(x + w, y, x + w, y + h, r); c.arcTo(x + w, y + h, x, y + h, r);
  c.arcTo(x, y + h, x, y, r); c.arcTo(x, y, x + w, y, r); c.closePath();
}
function fitMap() {
  const box = q('nk-mc');
  const s = Math.max(120, Math.floor(Math.min(box.clientWidth, box.clientHeight)));
  const d = Math.min(window.devicePixelRatio || 1, 3);
  if (s === side && d === dpr && base) return;
  side = s; dpr = d;
  mapCv.style.width = s + 'px'; mapCv.style.height = s + 'px';
  mapCv.width = Math.round(s * d); mapCv.height = Math.round(s * d);
  base = null;
}
function buildBase() {
  const g = geo(), G = BR.G || {};
  const cv = document.createElement('canvas'); cv.width = mapCv.width; cv.height = mapCv.height;
  const c = cv.getContext('2d'); c.scale(dpr, dpr);
  const S = side, k = S / (2 * g.HALF), X = x => (x + g.HALF) * k;
  c.fillStyle = '#20252c'; c.fillRect(0, 0, S, S);
  // дорожная разметка
  c.strokeStyle = 'rgba(255,255,255,.09)'; c.lineWidth = 1; c.setLineDash([4, 5]);
  for (let n = 1; n < g.N; n++) {
    const p = X(n * g.CELL - g.HALF);
    c.beginPath(); c.moveTo(p, 0); c.lineTo(p, S); c.moveTo(0, p); c.lineTo(S, p); c.stroke();
  }
  c.setLineDash([]);
  // кварталы
  const col = { res: '#39424e', down: '#566379', park: '#2c5a3a', ind: '#5a5247', stunt: '#6b4b28', garage: '#7d6c2c' };
  for (let i = 0; i < g.N; i++) for (let j = 0; j < g.N; j++) {
    let kind = 'res';
    try { if (typeof G.kindOf === 'function') kind = G.kindOf(i, j) || 'res'; } catch (e) { }
    const cx = (i + .5) * g.CELL - g.HALF, cz = (j + .5) * g.CELL - g.HALF;
    c.fillStyle = col[kind] || col.res;
    rr(c, X(cx - g.BLOCK / 2), X(cz - g.BLOCK / 2), g.BLOCK * k, g.BLOCK * k, Math.max(1, 2 * k));
    c.fill();
  }
  // здания: чем выше, тем светлее
  const bl = G.bList;
  if (Array.isArray(bl)) for (const b of bl) {
    if (!b || !isFinite(b.x) || !isFinite(b.z) || !(b.w > 0) || !(b.d > 0)) continue;
    c.fillStyle = 'rgba(255,255,255,' + (.05 + .28 * clamp((b.h || 8) / 150, 0, 1)).toFixed(3) + ')';
    c.fillRect(X(b.x - b.w / 2), X(b.z - b.d / 2), b.w * k, b.d * k);
  }
  // сетка секторов
  c.fillStyle = 'rgba(255,255,255,.42)'; c.textAlign = 'center'; c.textBaseline = 'middle';
  c.font = '700 ' + Math.max(8, Math.round(S / 55)) + 'px system-ui,sans-serif';
  for (let i = 0; i < g.N; i++) {
    const p = X((i + .5) * g.CELL - g.HALF);
    c.fillText(String.fromCharCode(65 + i % 26), p, 8);
    c.fillText(String(i + 1), 8, p);
  }
  c.strokeStyle = 'rgba(255,140,40,.7)'; c.lineWidth = 1.5;
  c.strokeRect(X(-g.BOUND), X(-g.BOUND), g.BOUND * 2 * k, g.BOUND * 2 * k);
  return cv;
}
function drawMap() {
  if (!mapOpen) return;
  fitMap(); if (!base) base = buildBase();
  const g = geo(), S = side, k = S / (2 * g.HALF), X = x => (x + g.HALF) * k, c = mctx;
  c.setTransform(1, 0, 0, 1, 0, 0); c.drawImage(base, 0, 0); c.setTransform(dpr, 0, 0, dpr, 0, 0);
  const tt = performance.now() / 1000;
  // машины NPC
  c.fillStyle = 'rgba(255,255,255,.6)';
  for (const v of BR.npcs || []) { if (!v || v.parked || !isFinite(v.x) || v.x > 9000) continue; c.fillRect(X(v.x) - 1, X(v.z) - 1, 2, 2); }
  // цель и радиусы
  if (target) {
    const px = X(target.x), pz = X(target.z);
    c.save(); c.beginPath(); c.rect(0, 0, S, S); c.clip();
    c.beginPath(); c.arc(px, pz, 440 * k, 0, 6.2832); c.fillStyle = 'rgba(255,154,48,.07)'; c.fill();
    c.strokeStyle = 'rgba(255,154,48,.9)'; c.lineWidth = 1.5; c.setLineDash([6, 5]); c.stroke(); c.setLineDash([]);
    c.beginPath(); c.arc(px, pz, 220 * k, 0, 6.2832); c.strokeStyle = 'rgba(255,110,40,.45)'; c.stroke();
    c.beginPath(); c.arc(px, pz, 55 * k, 0, 6.2832); c.fillStyle = 'rgba(255,60,30,.3)'; c.fill();
    c.strokeStyle = 'rgba(255,70,40,.9)'; c.stroke();
    c.restore();
    const pr = 7 + 2 * Math.sin(tt * 6);
    c.strokeStyle = '#ff3b2e'; c.lineWidth = 2;
    c.beginPath(); c.arc(px, pz, pr, 0, 6.2832); c.stroke();
    c.beginPath(); c.moveTo(px - pr - 7, pz); c.lineTo(px + pr + 7, pz); c.moveTo(px, pz - pr - 7); c.lineTo(px, pz + pr + 7); c.stroke();
    c.fillStyle = '#fff'; c.beginPath(); c.arc(px, pz, 2, 0, 6.2832); c.fill();
  }
  // игрок
  const F = focus();
  if (F) {
    c.save(); c.translate(X(F.x), X(F.z));
    c.beginPath(); c.arc(0, 0, 9 + 2 * Math.sin(tt * 3), 0, 6.2832); c.fillStyle = 'rgba(56,214,255,.2)'; c.fill();
    c.rotate(-(F.h || 0));
    c.beginPath(); c.moveTo(0, 7); c.lineTo(-5, -5); c.lineTo(0, -2); c.lineTo(5, -5); c.closePath();
    c.fillStyle = '#38d6ff'; c.fill(); c.strokeStyle = '#06222b'; c.lineWidth = 1.2; c.stroke();
    c.restore();
  }
}
function mapSet(e) {
  const r = mapCv.getBoundingClientRect(), g = geo();
  const x = clamp(((e.clientX - r.left) / r.width * 2 - 1) * g.HALF, -g.BOUND + 4, g.BOUND - 4);
  const z = clamp(((e.clientY - r.top) / r.height * 2 - 1) * g.HALF, -g.BOUND + 4, g.BOUND - 4);
  target = new T.Vector3(x, groundAt(x, z), z);
  placeMarker(); updateUI(); drawMap();
}
mapCv.addEventListener('pointerdown', e => {
  if (e.pointerType === 'mouse' && e.button !== 0) return;
  e.preventDefault(); dragging = true;
  try { mapCv.setPointerCapture(e.pointerId); } catch (x) { }
  mapSet(e);
});
mapCv.addEventListener('pointermove', e => { if (dragging) { e.preventDefault(); mapSet(e); } });
['pointerup', 'pointercancel'].forEach(ev => mapCv.addEventListener(ev, () => { dragging = false; }));

function openMap() {
  if (armed) setArmed(false);
  mapOpen = true; mapEl.style.display = 'block'; base = null; side = 0;
  updateUI(); drawMap();
}
function closeMap() { mapOpen = false; dragging = false; mapEl.style.display = 'none'; updateUI(); }
function clearTarget() { target = null; marker.visible = false; updateUI(); drawMap(); }

/* ---------- Состояние интерфейса ---------- */
function updateUI() {
  const st = busy ? 'busy' : target ? 'ready' : 'idle';
  panel.dataset.s = st;
  const l1 = busy ? 'БОЕГОЛОВКА В ПОЛЁТЕ' : armed ? 'КОСНИСЬ ЗЕМЛИ В МИРЕ' : target ? 'ЦЕЛЬ ЗАХВАЧЕНА' : 'ЦЕЛЬ НЕ ЗАДАНА';
  let l2 = 'открой карту и поставь метку', l3 = '';
  if (target) {
    const d = distToMe();
    l2 = 'СЕКТОР ' + sector(target.x, target.z) + (d == null ? '' : ' · ' + d + ' м от вас');
    l3 = 'X ' + Math.round(target.x) + '  Z ' + Math.round(target.z);
  }
  q('nk-l1').textContent = l1; q('nk-l2').textContent = l2;
  q('nk-m1').textContent = l1; q('nk-m2').textContent = l2; q('nk-m3').textContent = l3 || ' ';
  const ready = !!target && !busy;
  q('nk-go').disabled = !ready; q('nk-go').classList.toggle('lock', !ready);
  q('nk-mgo').disabled = !ready; q('nk-mgo').classList.toggle('lock', !ready);
  q('nk-mclr').disabled = !target || busy;
  q('nk-aim').disabled = busy;
  q('nk-aim').textContent = armed ? '✖ Отмена' : '🎯 Тап по миру';
  q('nk-dm').textContent = 'Урон машинам: ' + (destroy ? 'вкл' : 'выкл');
  toggleButton.classList.toggle('on', !!target);
}
function setArmed(v) { armed = v; document.body.classList.toggle('nk-aim', v); updateUI(); }

q('nk-om').onclick = () => openMap();
q('nk-mx').onclick = () => closeMap();
q('nk-mclr').onclick = () => clearTarget();
q('nk-aim').onclick = () => setArmed(!armed);
q('nk-go').onclick = () => launch();
q('nk-mgo').onclick = () => { if (!target || busy) return; closeMap(); launch(); };
q('nk-dm').onclick = () => { destroy = !destroy; BR.storage.set('destroy', destroy); updateUI(); };

// P — пульт, K — карта. N занято нитро, поэтому не используется.
window.addEventListener('keydown', e => {
  if (/INPUT|TEXTAREA/.test((e.target && e.target.tagName) || '')) return;
  if (mapOpen) {
    if (e.code === 'Escape' || e.code === 'KeyK') closeMap();
    e.stopPropagation(); e.preventDefault(); return;      // пока карта открыта, игра клавиши не получает
  }
  if (e.repeat) return;
  const playing = !!(BR.state && BR.state.mode === 'play');
  if (e.code === 'KeyP') { open = !open; if (!open && armed) setArmed(false); updateUI(); }
  else if (e.code === 'KeyK' && playing) openMap();
  else if (e.code === 'Escape' && armed) setArmed(false);
}, true);

/* ---------- Выбор цели тапом по миру ---------- */
let cvCache = null;
function getCanvas() {
  if (cvCache && cvCache.isConnected) return cvCache;
  let best = null, area = 0;
  document.querySelectorAll('canvas').forEach(c => { if (c.id === 'nk-cv') return; const a = c.width * c.height; if (a > area) { area = a; best = c; } });
  return (cvCache = best);
}
function protectedObjs() {
  const s = new Set();
  const add = o => { if (o && o.isObject3D) o.traverse(c => s.add(c)); };
  const list = [BR.player, BR.me].concat(BR.vehicles || [], BR.npcs || []);
  for (const v of list) {
    if (!v) continue;
    add(v);
