/* ---------- Взрыв ---------- */
// Настоящее повреждение машин через штатную цепочку BlockRush:
// crashFx -> hp/crumple -> разрыв графа -> физические pieces.
// Строения намеренно не скрываются: в BR API нет документированного
// интерфейса разрушения статических зданий.
// Направление от эпицентра наружу. В BlockRush мировые скорости машины — vx/vz,
// а kickBody принимает локальные компоненты и добавляет именно вращение.
function blastVehicle(v, p, radius) {
  const kickBody = BR.G && BR.G.kickBody;
  const crashFx = BR.G && BR.G.crashFx;
  if (!v || v.remote || v.parked || v.x > 9000 || !v.obj || typeof kickBody !== 'function') return false;

  const dx = v.x - p.x, dz = v.z - p.z;
  const dist = Math.hypot(dx, dz);
  if (dist > radius) return false;

  let dirX, dirZ;
  if (dist > .001) { dirX = dx / dist; dirZ = dz / dist; }
  else { dirX = Math.sin(v.h || 0); dirZ = Math.cos(v.h || 0); }

  // Формула преобразования мирового направления в локальные оси автомобиля
  // совпадает с используемой в collideCars / carHit.
  const sh = Math.sin(v.h || 0), ch = Math.cos(v.h || 0);
  const localX = dirX * ch - dirZ * sh;
  const localZ = dirX * sh + dirZ * ch;
  const falloff = Math.pow(Math.max(0, 1 - dist / radius), 1.15);
  const mass = Math.max(.7, Number(v.mass) || 1.3);

  // Линейный разгон отдельно от углового импульса. Тяжёлые машины получают
  // меньшую delta-v, но и грузовик всё равно заметно отлетает.
  const horizontal = clamp((24 + 30 * falloff) / Math.sqrt(mass), 10, 52);
  const lift = clamp((5 + 11 * falloff) / Math.pow(mass, .18), 4, 16);

  try {
    // kickBody включает stepFree и добавляет кувырок; сам по себе он не меняет vx/vz.
    kickBody(v, localX * 9, localZ * 9);
    v.far = false;                 // NPC больше не должен оставаться на упрощённом stepFar
    v.vx += dirX * horizontal;     // физический толчок всего корпуса
    v.vz += dirZ * horizontal;
    v.vy = Math.max(0, Number(v.vy) || 0) + lift;
    v.over = false;
    v.settle = 0;
    v.tipT = 0;

    // Умеренное повреждение с наветренной стороны: разрушение сопровождает
    // полёт, но не заменяет его и не превращает весь кузов в конфетти.
    if (destroy && typeof crashFx === 'function') {
      const hitX = -localX * .7, hitZ = -localZ * .7;
      const damageSpeed = 6 + 10 * falloff;
      crashFx(v, damageSpeed, hitX, hitZ, -localX, -localZ, 'body');
      // Кэш точек свободного тела должен учитывать уже оторванные детали.
      if (v._freeContactPoints) delete v._freeContactPoints;
    }
    return true;
  } catch (e) {
    console.warn('[nuke-remote] vehicle blast failed', e);
    return false;
  }
}

function blastPlayer(p, radius) {
  const me = BR.me;
  const hitAvatar = BR.G && BR.G.hitAvatar;
  if (!me || me.inCar || me.fly || me.lie > 0 || typeof hitAvatar !== 'function') return false;

  // В исходнике me.x/me.z — актуальная мировая позиция пешего персонажа.
  const dx = me.x - p.x, dz = me.z - p.z;
