  if (dist > radius) return false;
  const dirX = dist > .001 ? dx / dist : Math.sin(me.h || 0);
  const dirZ = dist > .001 ? dz / dist : Math.cos(me.h || 0);
  const falloff = Math.pow(Math.max(0, 1 - dist / radius), .8);
  const speed = 14 + 46 * falloff;
