  try {
    // Порядок аргументов взят из реального hitAvatar/rgKick в HTML-исходнике:
    // v задаёт перенос, nx/nz — нормаль наружу, vn — силу удара.
    hitAvatar(me, { vx: dirX * speed, vz: dirZ * speed }, dirX, dirZ, closing);
    return true;
  } catch (e) {
    console.warn('[nuke-remote] ragdoll launch failed', e);
