  let t = 0, carHits = 0, playerHit = false, playerNotified = false, carsNotified = false;
  const hit = new Set();
  const duration = 1.8;
  const maxRadius = radius || 440;

  fx.push({
    u(dt) {
      t += dt;
      const waveRadius = maxRadius * clamp(t / duration, 0, 1);
      const all = [];
      if (Array.isArray(BR.vehicles)) all.push(...BR.vehicles);
      if (Array.isArray(BR.npcs)) all.push(...BR.npcs);

      for (const v of all) {
        if (!v || hit.has(v)) continue;
        const dx = v.x - p.x, dz = v.z - p.z;
        if (Math.hypot(dx, dz) > waveRadius) continue;
        hit.add(v);
        if (blastVehicle(v, p, maxRadius)) carHits++;
      }

      const me = BR.me;
      if (!playerHit && me && !me.inCar && !me.fly && !(me.lie > 0)) {
        const md = Math.hypot(me.x - p.x, me.z - p.z);
        if (md <= waveRadius) playerHit = blastPlayer(p, maxRadius);
      }

      if (playerHit && !playerNotified) {
        playerNotified = true;
        BR.toast('Ударная волна подхватила персонажа!');
      }
      if (t >= duration && carHits && !carsNotified) {
