  });
}
function boom(p) {
  flash(); boomSound();
  const cd = BR.camera.position.distanceTo(p);
  shakeAmp = clamp(30 * 400 / (cd + 200), 4, 30); shakeDur = shakeT = 5;
  const parts = [];
  const add = (geo, color, op, extra) => {
    const m = new T.Mesh(geo, new T.MeshBasicMaterial(Object.assign({ color, transparent: true, opacity: op, depthWrite: false }, extra || {})));
    root.add(m); parts.push(m); return m;
  };
