BR.on('tick', dt0 => {
  try {
    const dt = Math.min(dt0 || .016, .05);
    const playing = !!(BR.state && BR.state.mode === 'play');
    if (!playing && mapOpen) closeMap();
    const want = playing && open;
    toggleButton.style.display = playing ? 'flex' : 'none';
    if (want !== shown) { panel.style.display = want ? 'block' : 'none'; shown = want; if (want) updateUI(); }
    toggleButton.setAttribute('aria-label', open ? 'Скрыть ядерный пульт' : 'Открыть ядерный пульт');
    uiT += dt; if (uiT > .25) { uiT = 0; if (want || mapOpen) updateUI(); }
    if (mapOpen) drawMap();
    if (marker.visible) {
      const k = performance.now() / 1000;
      r1.scale.setScalar(1 + .08 * Math.sin(k * 6)); r2.rotation.z = k * 2; beam.material.opacity = .3 + .2 * Math.sin(k * 5);
    }
    for (let i = fx.length - 1; i >= 0; i--) {
      let alive = false;
      try { alive = fx[i].u(dt); } catch (e) { console.error(e); }
      if (!alive) { try { fx[i].d(); } catch (e) { console.error(e); } fx.splice(i, 1); }
    }
    if (shakeT > 0) {
      shakeT -= dt;
      const cv = getCanvas();
      if (cv) {
        if (shakeT > 0) {
          const a = shakeAmp * Math.pow(shakeT / shakeDur, 2);
          cv.style.transform = 'translate(' + (Math.random() - .5) * 2 * a + 'px,' + (Math.random() - .5) * 2 * a + 'px) scale(1.04)';
        } else cv.style.transform = '';
      }
    }
  } catch (e) { console.error(e); }
});
